import androidx.compose.ui.res.painterResource
import androidx.compose.ui.unit.Dp

// Generated by scripts/import-hugeicons.mjs. Change the mapping there, then regenerate.
enum class Glyph(@DrawableRes val resource: Int) {
    Back(R.drawable.cue_back),
    Next(R.drawable.cue_next),
    Close(R.drawable.cue_close),
    Plus(R.drawable.huge_plus),
    Search(R.drawable.huge_search),
    User(R.drawable.huge_user),
    Settings(R.drawable.huge_settings),
    Computer(R.drawable.huge_computer),
    More(R.drawable.huge_more),
    Up(R.drawable.huge_up),
    Check(R.drawable.huge_check),
    Mic(R.drawable.huge_mic),
    Box(R.drawable.huge_box),
    Book(R.drawable.huge_book),
    Memory(R.drawable.huge_memory),
    Chat(R.drawable.huge_chat),
    File(R.drawable.huge_file),
    Mail(R.drawable.huge_mail),
    Phone(R.drawable.huge_phone),
    Wallet(R.drawable.huge_wallet),
    Globe(R.drawable.huge_globe),
    Moon(R.drawable.huge_moon),
    Heart(R.drawable.huge_heart),
    Help(R.drawable.huge_help),
    Edit(R.drawable.huge_edit),
    Copy(R.drawable.huge_copy),
    Pin(R.drawable.huge_pin),
    Camera(R.drawable.huge_camera),
    Image(R.drawable.huge_image),
    Clip(R.drawable.huge_clip),
    Location(R.drawable.huge_location),
    Bot(R.drawable.huge_bot),
    Group(R.drawable.huge_group),
    Scan(R.drawable.huge_scan),
    Skill(R.drawable.huge_skill),
    Terminal(R.drawable.huge_terminal),
    Swap(R.drawable.huge_swap),
    External(R.drawable.huge_external),
    Stop(R.drawable.huge_stop),
    Trash(R.drawable.huge_trash),
    Square(R.drawable.huge_square),
    Brush(R.drawable.huge_brush),
}

@Composable
fun Icon(
    glyph: Glyph,
    modifier: Modifier = Modifier,
    tint: Color = LocalContentColor.current,
    size: Dp = Cue.IconSize,
) {
    androidx.compose.material3.Icon(
        painter = painterResource(glyph.resource),
        contentDescription = null, // The containing control owns its accessible label.
        modifier = modifier.size(size),
        tint = tint,
    )
}
